​
        // 定义方向
        int direct[2][4] = {
            {1, 0, -1, 0},
            {0, 1,  0, -1}
        };
        queue<pair<int,int>>  q;
        q.push({x1,y1});
        q.push({x2,y2});
        int count = 0;
        // bfs 使用队列模拟
        while (!q.empty()) {
            queue<pair<int,int>>  tmp;
​
            while (!q.empty()) {
                pair<int, int> p = q.front();
                q.pop();
                int x = p.first;
