                    if ( matrix[x1][y1] == 1) {
                        continue;
                    }
​
                    matrix[x1][y1] = 1;

                    tmp.push({x1, y1});
                }
            }
            count++;
            q = tmp;
        }
        cout << count - 1;
        return 0;
    }

