 * @param {*} l 扩散点位置为k,l
 */
function getResult(m, n, i, j, k, l) {
  const matrix = new Array(m).fill(0).map(() => new Array(n).fill(0));
  matrix[i][j] = 1;
  matrix[k][l] = 1;
​
  // count记录未被扩散的点的数量
  let count = m * n - 2;
​
  // 多源BFS实现队列
  let queue = [
    [i, j],
    [k, l],
  ];
​
  // 上下左右偏移量
  const offsets = [
    [1, 0],
    [-1, 0],
    [0, 1],
    [0, -1],
  ];
​
  let day = 0;
​
  // 如果扩散点没有了，或者所有点已被扩散，则停止循环
  while (queue.length > 0 && count > 0) {
    const newQueue = [];
​
    for (const [x, y] of queue) {
      for (let [offsetX, offsetY] of offsets) {
        const newX = x + offsetX;
        const newY = y + offsetY;
​
        if (
          newX >= 0 &&
          newX < m &&
          newY >= 0 &&
          newY < n &&
          matrix[newX][newY] == 0
        ) {
          // 将点被扩散的时间记录为该点的值
          matrix[newX][newY] = 1;
          // 被扩散到的点将变为新的扩散源
          newQueue.push([newX, newY]);
          // 未被扩散点的数量--
          count--;
        }
      }
    }
​
    queue = newQueue;
    day++;
  }
​
  return day;
}

