import (
    "fmt"
    "strconv"
    "strings"
)
​
func main() {
    var input string
    fmt.Scan(&input)
​
    // 处理输入
    parts := strings.Split(input, ",")
    m, _ := strconv.Atoi(parts[0])
    n, _ := strconv.Atoi(parts[1])
    x1, _ := strconv.Atoi(parts[2])
    y1, _ := strconv.Atoi(parts[3])
    x2, _ := strconv.Atoi(parts[4])
    y2, _ := strconv.Atoi(parts[5])
​
    // 初始化矩阵
    matrix := make([][]int, m)
    for i := range matrix {
        matrix[i] = make([]int, n)
    }
    matrix[x1][y1] = 1
    matrix[x2][y2] = 1
​
    directions := [][2]int{
        {1, 0},
        {0, 1},
        {-1, 0},
        {0, -1},
    }
​
    // 初始化队列
    queue := [][2]int{{x1, y1}, {x2, y2}}
    count := 0
​
    // BFS 使用队列模拟
    for len(queue) > 0 {
        newQueue := [][2]int{}
        for _, p := range queue {
            x, y := p[0], p[1]
            for _, d := range directions {
                nx, ny := x+d[0], y+d[1]
                if nx < 0 || nx >= m || ny < 0 || ny >= n {
                    continue
                }
                if matrix[nx][ny] == 1 {
                    continue
                }
                matrix[nx][ny] = 1
                newQueue = append(newQueue, [2]int{nx, ny})
            }
        }
        count++
        queue = newQueue
    }
​
    fmt.Println(count - 1)
}
